'use strict';
// Java's file rules (src/languages/java/rules.js, J1): source, test and generated files,
// and the project a file belongs to.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { javaRules, javaProjectOf, GENERATED_HEAD_CHARS } = require('../src/languages/java/rules');

test('a .java file is Java source; tool state and IDE output are not', () => {
  for (const p of ['A.java', 'src/main/java/com/x/A.java', 'gson/src/test/java/B.java', 'a\\b\\C.java', 'rebuild/X.java', 'outer/X.java', 'about/X.java', 'pkg/.gradlew/X.java', 'pkg/target/X.java']) {
    assert.equal(javaRules.handles(p), true, p);
  }
  for (const p of ['A.kt', 'A.class', 'A.java.orig', 'A.JAVA', 'A.javax', 'pom.xml', '.gradle/caches/X.java', 'mod/.gradle/X.java', 'out/production/X.java', 'mod/out/X.java', 'out\\X.java']) {
    assert.equal(javaRules.handles(p), false, p);
  }
});

test('a test is under src/test/ or named *Test, *Tests, *IT or *TestCase', () => {
  for (const p of ['src/test/java/com/x/Helper.java', 'module/src/test/java/Helper.java', 'a/b/src/test/resources/X.java', 'ATest.java', 'x/ATests.java', 'x/AIT.java', 'x/ATestCase.java', 'module\\src\\test\\java\\H.java', 'x\\ATest.java']) {
    assert.equal(javaRules.isTest(p), true, p);
  }
  for (const p of ['TestUtils.java', 'Contest.java', 'src/testing/X.java', 'src/main/java/X.java', 'x/Test.java.orig', 'x/ATest.javax', 'x/Attest.java', 'x/Unit.java', 'x/BaseTest2.java', 'mysrc/test/X.java', 'src/tests/X.java']) {
    // `Test.java` alone and `Unit.java` are not tests by name; `Contest` ends in `test`, lower case.
    assert.equal(javaRules.isTest(p), false, p);
  }
});

test('generated by directory: build output and generator output', () => {
  for (const p of ['target/classes/X.java', 'mod/target/generated-sources/X.java', 'build/generated/X.java', 'mod/build/X.java', 'src/generated-sources/X.java', 'a/generated-test-sources/X.java', 'mod\\target\\X.java']) {
    assert.equal(javaRules.isGenerated(p, 'class X {}\n'), true, p);
  }
  for (const p of ['rebuild/X.java', 'outer/X.java', 'src/main/java/X.java', 'targets/X.java', 'src/generated/X.java', 'mybuild/X.java']) {
    assert.equal(javaRules.isGenerated(p, 'class X {}\n'), false, p);
  }
});

test('generated by a header comment or an annotation on the top-level type', () => {
  const yes = (/** @type {string} */ text, /** @type {string} */ why) => assert.equal(javaRules.isGenerated('A.java', text), true, why);
  const no = (/** @type {string} */ text, /** @type {string} */ why) => assert.equal(javaRules.isGenerated('A.java', text), false, why);
  yes('// Generated by the protocol buffer compiler.  DO NOT EDIT!\npackage x;\nclass A {}\n', 'line comment');
  yes('/* Generated by tool */\npackage x;\nclass A {}\n', 'block comment');
  yes('/*\n * Generated by tool 1.2\n */\npackage x;\nclass A {}\n', 'block comment, own line');
  yes('/**\n * Parser.\n * @Generated\n */\npackage x;\nclass A {}\n', 'javadoc @Generated');
  yes('// Generated by tool\r\npackage x;\r\nclass A {}\r\n', 'CRLF line ends');
  yes('/* licence */\n// Generated by tool\npackage x;\nclass A {}\n', 'after a licence comment');
  yes('package x;\n\n@Generated("by tool")\npublic class A {}\n', '@Generated');
  yes('package x;\nimport javax.annotation.Generated;\n\n@Generated(value = "tool", date = "now")\npublic final class A {}\n', '@Generated with arguments');
  yes('package x;\n\n@javax.annotation.Generated("x")\npublic class A {}\n', 'qualified');
  yes('package x;\n\n@javax.annotation.processing.Generated(value = "x",\n    comments = "y")\npublic class A {}\n', 'jakarta/javax processing, multi-line arguments');
  yes('package x;\n\n@SuppressWarnings("all")\n@Generated("x")\npublic interface A {}\n', 'after another annotation');
  yes('package x;\n\n@Generated("x") public enum A { B }\n', 'on the declaration line');
  yes('package x;\n\n@Generated("x")\npublic @interface A {}\n', 'on an annotation type');
  yes('package x;\n\n@Generated("x")\npublic record A(int b) {}\n', 'on a record');
  no('package x;\n\nclass A {}\n', 'no marker');
  no('package x;\n\n/** Generated code is not edited by hand. */\nclass A {}\n', 'prose about generation');
  no('package x;\n\n// This is not Generated by tool\nclass A {}\n', 'not at the start of the comment');
  no('// generated by tool\npackage x;\nclass A {}\n', 'case-sensitive');
  no('package x;\n\n@GeneratedValue\nclass A {}\n', 'another annotation with the prefix');
  no('package x;\n\n@MyGenerated\nclass A {}\n', 'another annotation with the suffix');
  no('package x;\n\nclass A {\n  // Generated by hand\n  @Generated void f() {}\n}\n', 'after the top-level type');
  no('package x;\n\nclass A {\n  String s = "@Generated";\n}\n', 'in a string, after the type');
  no('package x;\n\n@Foo(A.class)\n@Bar\nclass A {}\n\n// Generated by tool\n', 'comment after the type');
  no('', 'an empty file');
});

test('the generated marker is looked for only in the head of the file', () => {
  const late = `${'// filler\n'.repeat(Math.ceil(GENERATED_HEAD_CHARS / 10))}// Generated by x\npackage x;\nclass A {}\n`;
  assert.equal(javaRules.isGenerated('A.java', late), false, 'past the head: analysed, as documented');
});

test('javaProjectOf: the nearest pom.xml, build.gradle or build.gradle.kts', () => {
  const repo = fs.mkdtempSync(path.join(os.tmpdir(), 'it-java-rules-'));
  try {
    fs.mkdirSync(path.join(repo, 'gson', 'src', 'main', 'java'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'plain', 'src'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'apps', 'kts', 'src'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'apps', 'groovy'), { recursive: true });
    fs.writeFileSync(path.join(repo, 'pom.xml'), '');
    fs.writeFileSync(path.join(repo, 'gson', 'pom.xml'), '');
    fs.writeFileSync(path.join(repo, 'apps', 'kts', 'build.gradle.kts'), '');
    fs.writeFileSync(path.join(repo, 'apps', 'groovy', 'build.gradle'), '');
    assert.deepEqual(javaProjectOf('Top.java', repo), { component: '(root)', projectRoot: '' });
    assert.deepEqual(javaProjectOf('plain/src/X.java', repo), { component: '(root)', projectRoot: '' }, 'falls back to the root project');
    assert.deepEqual(javaProjectOf('gson/src/main/java/X.java', repo), { component: 'gson', projectRoot: 'gson' }, 'multi-module, nested pom.xml');
    assert.deepEqual(javaProjectOf('gson\\src\\main\\java\\X.java', repo), { component: 'gson', projectRoot: 'gson' }, 'Windows path');
    assert.deepEqual(javaProjectOf('apps/kts/src/X.java', repo), { component: 'apps/kts', projectRoot: 'apps/kts' }, 'build.gradle.kts');
    assert.deepEqual(javaProjectOf('apps/groovy/X.java', repo), { component: 'apps/groovy', projectRoot: 'apps/groovy' }, 'build.gradle');
    fs.rmSync(path.join(repo, 'pom.xml'));
    assert.deepEqual(javaProjectOf('plain/src/X.java', repo), { component: '(no pom.xml or build.gradle)', projectRoot: '' });
    assert.deepEqual(javaProjectOf('Top.java', repo), { component: '(no pom.xml or build.gradle)', projectRoot: '' });
    assert.deepEqual(javaProjectOf('gson/src/main/java/X.java', repo), { component: 'gson', projectRoot: 'gson' });
  } finally {
    fs.rmSync(repo, { recursive: true, force: true });
  }
});
